    [Theory]
    [MemberData(nameof(SourceCases))]
    public void Fresh_generation_breakability_matches_actual_original_without_changing_guard_inputs(
        string profile, string encoded, int expected, bool kill, string before, string after, string rngAfter, int nextRandom)
    {
        // Actual official1.4.5.8 CheckTileBreakability, fresh hardModefalse. Whole80x80 grid
        // and all56 RNG slots/cursor were observed independently; selected0/1/2 rows also KillTile.
        _ = profile;
        var workspace = new Workspace(80, 80);
        foreach (string member in encoded.Split(';'))
        {
            int[] values = member.Split(',').Select(int.Parse).ToArray();
            var tile = new WorldTile { Type = (ushort)values[2], FrameX = (short)values[3], FrameY = (short)values[4],
                Flags = (values[5] != 0 ? WorldTileFlags.Active : WorldTileFlags.None) |
                    (values[6] != 0 ? WorldTileFlags.Inactive : WorldTileFlags.None) };
            workspace.TileStore.Set(values[0], values[1], in tile);
        }
        var random = new RandomAdapter(1458);
        string originalRandom = random.Fingerprint();
        var framer = new GenerationTileFraming1458(workspace.TileStore, random);
        Assert.Equal(before, HashFixture(workspace));
        Assert.Equal(expected, framer.TileBreakability(40, 40));
        Assert.Equal(before, HashFixture(workspace));
        Assert.Equal(originalRandom, random.Fingerprint());
        if (kill)
            framer.KillTile(40, 40);
        Assert.Equal(after, HashFixture(workspace));
        Assert.Equal(rngAfter, random.Fingerprint());
        Assert.Equal(nextRandom, random.Next());
    }

    private static string HashFixture(Workspace workspace)
    {
        var snapshot = new StringBuilder(workspace.WidthTiles * workspace.HeightTiles * 20);
        for (int x = 0; x < workspace.WidthTiles; x++)
        for (int y = 0; y < workspace.HeightTiles; y++)
        {
            WorldTile tile = workspace.TileStore.Get(x, y);
            snapshot.Append(tile.IsActive ? '1' : '0').Append(',').Append(tile.Type).Append(',').Append(tile.Wall).Append(',')
                .Append(tile.FrameX).Append(',').Append(tile.FrameY).Append(',').Append(tile.LiquidAmount).Append(';');
        }
        return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(snapshot.ToString())));
    }

    private sealed class RandomAdapter(int seed) : IWorldGenerationVanillaRandom
    {
        private readonly VanillaUnifiedRandom1458 random = new(seed);
        public string Fingerprint()
        {
            const System.Reflection.BindingFlags flags = System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic;
            var cursor = typeof(VanillaUnifiedRandom1458).GetField("inext", flags)!.GetValue(random);
            var slots = (int[])typeof(VanillaUnifiedRandom1458).GetField("seedArray", flags)!.GetValue(random)!;
            return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(cursor + ";" + string.Join(",", slots))));
        }
        public int Next() => random.Next();
        public int Next(int maxValue) => random.Next(maxValue);
        public int Next(int minValue, int maxValue) => random.Next(minValue, maxValue);
        public double NextDouble() => random.NextDouble();
        public void NextBytes(byte[] buffer) => random.NextBytes(buffer);
    }
